catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }

    // Definir limite para o dia de ontem
    var limitDay = new Date(); // Data de hoje
    limitDay.setDate(limitDay.getDate() - 1); // Subtrai 1 dia (ontem)

    // Verificar se a data foi preenchida corretamente (novo valor)
    var parts = newValue.split(" - "); // Exemplo: "22/01/25 - 22/01/27"
    var dateParts = parts[0].split("/"); // Separando o valor "22/01/25" em ["22", "01", "25"]

    // Convertemos para um objeto Date
    var refundDay = new Date(dateParts[2], dateParts[1] - 1, dateParts[0]); // (25, 0, 22) para 22/01/25

    // Comparar com a data limite de ontem
    if (refundDay.getTime() < limitDay.getTime()) {
        g_form.addErrorMessage("You can only register for courses one day in advance.");
        g_form.clearValue("date");
		g_form.clearValue("course");
		g_form.clearValue("training_agenda")
    } else {
        g_form.clearMessages();
    }
}
